/**
 * Turns a title into a URL-safe slug.
 *
 * Shared by the project service, the technology service and the seed dataset,
 * so a slug generated by seeding is byte-identical to one generated through
 * the admin panel.
 */
export function slugify(input: string): string {
  return input
    .toLowerCase()
    .normalize('NFKD')
    // Strip diacritics so "Café" becomes "cafe" rather than "caf".
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 100)
}

/**
 * Finds a slug that is not already taken, appending -2, -3, … as needed.
 *
 * Takes an async existence check rather than a repository, so it works
 * unchanged against any storage backend and is trivially unit-testable.
 *
 * Note this is a check-then-write, which is not atomic. That is acceptable
 * here: there is exactly one admin, so two conflicting writes cannot race. The
 * database-level unique index remains the real guarantee once MongoDB is in
 * place, and a violation there surfaces as the same 409.
 */
export async function generateUniqueSlug(
  desired: string,
  exists: (slug: string) => Promise<boolean>
): Promise<string> {
  const base = slugify(desired) || 'item'

  if (!(await exists(base))) return base

  for (let suffix = 2; suffix < 1000; suffix += 1) {
    const candidate = `${base}-${suffix}`
    if (!(await exists(candidate))) return candidate
  }

  // Effectively unreachable; a timestamp guarantees termination.
  return `${base}-${Date.now()}`
}
